<?php
 namespace App\Http\Controllers; use App\Http\Requests\LotRequest; use App\Models\Lot; use App\Models\Project; class LotController extends Controller { public function index() { $lots = Lot::with('project')->get(); return view('kavling.index', [ 'lots' => $lots, ]); } public function create() { $projects = Project::all(); return view('kavling.create', compact('projects')); } public function store(LotRequest $request) { Lot::create($request->validated()); return redirect()->route('kavling.index')->with('success', 'Kavling ditambahkan'); } public function destroy(Lot $kavling) { $kavling->delete(); return redirect()->route('kavling.index')->with('success', 'Kavling dihapus'); } public function edit(Lot $kavling) { $projects = Project::all(); return view('kavling.edit', [ 'lot' => $kavling, 'projects' => $projects, ]); } public function update(LotRequest $request, Lot $kavling) { $kavling->update($request->validated()); return redirect()->route('kavling.index')->with('success', 'Kavling diperbarui'); } public function pricing(Lot $lot) { $basePrice = (int) ($lot->base_price ?? 0); $dpPercent = 20; $dpNominal = $basePrice > 0 ? (int) round($basePrice * ($dpPercent / 100)) : 0; return response()->json([ 'id' => $lot->id, 'project' => optional($lot->project)->name, 'block_number' => $lot->block_number, 'area' => $lot->area, 'base_price' => $basePrice, 'status' => $lot->status, 'is_sold' => (bool) $lot->sale()->exists(), 'payment_defaults' => [ 'dp_percent' => $dpPercent, 'dp_nominal' => $dpNominal, 'tenor_months' => 12, 'due_day' => 10, ], ]); } } 